content:
{
 "kind": "sequence",
 "format": 1,
 "id": "seq_cphl_booth_break",
 "name": "Cluster Puck: the booth, into the intermission",
 "set": "set_slush_booth",
 "roles": {
  "pbp": {
   "mark": "pbp",
   "label": "Play-by-play"
  },
  "col": {
   "mark": "col",
   "label": "Colour"
  }
 },
 "wall": "feed",
 "wallText": "{venue}",
 "wallSub": "{show}",
 "beats": [
  {
   "id": "b1",
   "shot": {
    "cam": "wide",
    "frame": "two",
    "on": [
     "pbp",
     "col"
    ],
    "move": "none",
    "cut": "dissolve"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "That's the end of the {section}. {away} {awayScore}, {home} {homeScore}.",
     "Horn goes on the {section}. {away} {awayScore}, {home} {homeScore}."
    ]
   },
   "gfx": [
    {
     "kind": "score",
     "title": "{status}",
     "left": "{away}",
     "leftScore": "{awayScore}",
     "right": "{home}",
     "rightScore": "{homeScore}",
     "sub": "{venue}",
     "at": 0.2,
     "for": 0
    }
   ]
  },
  {
   "id": "b2",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "{lastGoal.name} had the last one. {goalsSaid} so far.",
     "{goalsSaid} already, and {lastGoal.name} scored the latest."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "goalCount",
     "op": ">",
     "value": 0
    },
    {
     "fact": "lastGoal.name",
     "op": "has"
    }
   ]
  },
  {
   "id": "b3",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "Still nothing on the board. Both goalies have been good.",
     "No goals yet. {shots} shots and nobody's found a way through."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "goalCount",
     "op": "=",
     "value": "0"
    }
   ]
  },
  {
   "id": "b4",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "And we've had {fightsSaid}. Nobody's backing down tonight."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "fightCount",
     "op": ">",
     "value": 0
    }
   ]
  },
  {
   "id": "b5",
   "shot": {
    "cam": "cam1",
    "frame": "two",
    "on": [
     "pbp",
     "col"
    ],
    "move": "pull",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "We'll go to the desk. Back for the {nextOrd} in a bit.",
     "Let's head back to the studio. We'll see you for the {nextOrd}."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "section",
     "op": "!=",
     "value": "3rd"
    }
   ]
  },
  {
   "id": "b6",
   "shot": {
    "cam": "cam1",
    "frame": "two",
    "on": [
     "pbp",
     "col"
    ],
    "move": "pull",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "Tied after sixty minutes. We'll go to the desk, and then it's overtime.",
     "Sixty minutes and nothing settled. Over to the desk, and we'll be back for overtime."
    ]
   },
   "gfx": [],
   "if": [
    {
     "fact": "section",
     "op": "=",
     "value": "3rd"
    }
   ]
  }
 ]
}
